/* Analysis charts adapt lieflat F2 Hairline Line and F5 Tick Rows.
   Fixed synthetic daily rates; all summary calculations use the same series. */
const ANALYSIS_COLORS={BG:'#e9f3fa',TXT:'#3b3e42',MUT:'#536777',GRID:'#b8cedd',DATA:'#597e99',HERO:'#314e64'};
const analysisState={range:7,index:null,why:false};
const analysisWeeks=[[40,50,60,60,70,80,60],[50,50,60,60,70,90,60],[40,60,60,60,80,90,65],[50,60,60,70,80,100,70]];
const analysisAll=analysisWeeks.flat().map((v,i)=>({v,date:new Date(2026,7,24+i),weekend:i%7>4}));
const analysisData=()=>analysisAll.slice(-analysisState.range);
const average=a=>a.reduce((n,d)=>n+d.v,0)/a.length;
const pct=v=>Number(v.toFixed(1)).toString();
const dateLabel=d=>d.toLocaleDateString(lang==='en'?'en-US':'zh-CN',{month:'short',day:'numeric'});

function cleanupAnalysis(){cancelAnimationFrame(metricFrame);cancelAnimationFrame(morphFrame);}
function renderAnalysis(){
 const data=analysisData(),mean=average(data),weekdays=average(data.filter(d=>!d.weekend)),weekends=average(data.filter(d=>d.weekend));
 document.getElementById('app').innerHTML=`<div class="analysis-page"><header class="analysis-top"><span class="sample-label">${tr('ANALYSIS','经营分析')}</span><button id="analysis-language">${tr('中文','EN')}</button></header><section class="analysis-canvas" aria-labelledby="analysis-title"><div class="analysis-eyebrow">${tr('YOUR STAY, IN PERSPECTIVE','看懂你的民宿')}</div><div class="metric-heading"><h1 id="analysis-title">${tr('Occupancy','入住率')}</h1><span class="analysis-demo">${tr('Demo data','示例数据')}</span></div><div class="occupancy-number"><span id="occupancy-value">${pct(mean)}</span><span>%</span></div><div class="metric-context"><p id="analysis-period">${dateLabel(data[0].date)} – ${dateLabel(data.at(-1).date)}</p><p id="analysis-delta">${analysisState.range===7?tr('↑ 5 percentage points from last week','↑ 较上周提升 5 个百分点'):tr('Four-week average · Sample bookings','四周平均 · 示例预订')}</p></div><div class="analysis-toolbar"><div class="range-switch" role="group" aria-label="${tr('Chart time range','图表时间范围')}"><button data-range="7" aria-pressed="${analysisState.range===7}">${tr('7 days','7 天')}</button><button data-range="28" aria-pressed="${analysisState.range===28}">${tr('28 days','28 天')}</button></div><button class="period-reset" id="period-reset">${tr('Period average','期间平均')}</button></div><div class="occupancy-plot" id="occupancy-plot"><div class="chart-tooltip" id="chart-tooltip" hidden></div><svg id="occupancy-chart" viewBox="0 0 360 245" role="img" aria-label="${tr('Daily occupancy. Hollow points mark weekends.','每日入住率，空心圆表示周末。')}"></svg><input class="chart-scrubber" id="chart-scrubber" type="range" min="0" max="${data.length-1}" value="0" aria-label="${tr('Select date on occupancy chart','选择入住率图表日期')}"></div><div class="chart-key"><span>● ${tr('Weekday','工作日')} &nbsp; ○ ${tr('Weekend','周末')}</span><span>${tr('Drag to explore','拖动查看')}</span></div><details class="chart-data"><summary>${tr('View daily values','查看每日数据')}</summary><table><thead><tr><th>${tr('Date','日期')}</th><th>${tr('Occupancy','入住率')}</th></tr></thead><tbody>${data.map(d=>`<tr><td>${dateLabel(d.date)}</td><td>${d.v}%</td></tr>`).join('')}</tbody></table></details></section><section class="comparison-section" id="day-comparison"><div class="analysis-section-head"><h2>${tr('Two different rhythms','两种经营节奏')}</h2><span>${tr('Same period','同一期间')}</span></div><svg id="day-comparison-chart" viewBox="0 0 360 153" role="img" aria-label="${tr(`Weekdays ${pct(weekdays)}%, weekends ${pct(weekends)}%`,`工作日 ${pct(weekdays)}%，周末 ${pct(weekends)}%`)}"></svg><p class="analysis-source">${tr('Mon–Fri vs Sat–Sun · Each tick = 1 percentage point','周一至周五 / 周六至周日 · 每条刻度 = 1 个百分点')}</p></section><section class="ai-interpretation"><span class="analysis-eyebrow">${tr('AI INTERPRETATION','AI 解读')}</span><h2>${tr('Weekdays are your<br>main opportunity.','机会，藏在工作日。')}</h2><p>${tr('Most remaining availability is concentrated between Monday and Thursday.','剩余空房主要集中在周一至周四。')}</p><div class="insight-actions"><button id="analysis-why" aria-expanded="${analysisState.why}" aria-controls="analysis-evidence">${tr('Why?','为什么？')} <span aria-hidden="true">${analysisState.why?'−':'+'}</span></button><button id="analysis-action">${tr('What can I do?','我可以做什么？')} ${svg('arrow')}</button></div><div class="analysis-evidence ${analysisState.why?'expanded':''}" id="analysis-evidence" ${analysisState.why?'':'inert'}><div><p>${tr('The highlighted dots are Monday–Thursday. In this period, they account for','图中强调的点为周一至周四。这些日期占本期剩余空房的')} <strong id="availability-share"></strong>${tr('. A weekday-focused offer could address that gap.','，可以尝试面向工作日的住宿推广。')}</p><p class="analysis-source">${tr('Based on sample booking rates, equal daily capacity. This is not a market forecast.','依据每日容量相同的示例预订率，不代表市场预测。')}</p><button class="evidence-chart" id="evidence-chart">${tr('See highlighted dates ↑','查看强调日期 ↑')}</button></div></div></section><section class="exploration"><span class="analysis-eyebrow">${tr('LOOK A LITTLE CLOSER','再深入一点')}</span><h2>${tr('Explore your performance','探索经营表现')}</h2><button class="explore-row" id="explore-trend"><span><b>${tr('Occupancy trend','入住率趋势')}</b><small>${tr('A wider view of the last 28 days','查看最近 28 天的变化')}</small></span>${svg('insight')}</button><details class="booking-pace"><summary><span><b>${tr('Booking pace','预订进度')}</b><small>${tr('How next week is filling up','下周的预订情况')}</small></span><span class="expand-mark">+</span></summary><div class="pace-content"><div><strong>32</strong><span>${tr('room nights booked','间夜已预订')}</span><span class="pace-change">${tr('+6 vs the same lead time','较上周同一提前期 +6')}</span></div><p>${tr('For Sep 21–27, 32 of 70 room nights are booked as of Sep 18. Last week had 26 booked at the same lead time.','截至 9 月 18 日，9 月 21–27 日的 70 个可售间夜已订 32 个；上周同一提前期已订 26 个。')}</p><small>${tr('Forward bookings · Separate from realised occupancy above','未来预订 · 与上方入住率分开统计')}</small></div></details><button class="explore-row" id="explore-weekdays"><span><b>${tr('Weekday vs weekend','工作日与周末')}</b><small>${tr('See where availability sits','比较空房分布')}</small></span>${svg('arrow')}</button><button class="explore-row" id="explore-rooms"><span><b>${tr('Room performance','房型表现')}</b><small>${tr('Compare your rooms, side by side','对比不同房型')}</small></span>${svg('arrow')}</button></section><p class="analysis-footer">${tr('SAMPLE DATA · NO CONNECTED PLATFORMS','示例数据 · 未连接外部平台')}</p></div>`;
 document.getElementById('analysis-language').onclick=()=>{lang=lang==='en'?'zh':'en';render()};
 document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>switchAnalysisRange(Number(b.dataset.range)));
 document.getElementById('period-reset').onclick=()=>selectAnalysisPoint(null);
 document.getElementById('analysis-why').onclick=()=>{analysisState.why=!analysisState.why;applyEvidence();};
 document.getElementById('analysis-action').onclick=()=>analysisSheet('offer');
 document.getElementById('evidence-chart').onclick=()=>document.getElementById('occupancy-plot').scrollIntoView({behavior:motion()?'smooth':'instant',block:'center'});
 document.getElementById('explore-trend').onclick=()=>{switchAnalysisRange(28);document.getElementById('analysis-title').scrollIntoView({behavior:motion()?'smooth':'instant',block:'start'})};
 document.getElementById('explore-weekdays').onclick=()=>{document.getElementById('day-comparison').scrollIntoView({behavior:motion()?'smooth':'instant',block:'center'});if(motion())document.getElementById('day-comparison').animate([{opacity:.4},{opacity:1}],{duration:450})};
 document.getElementById('explore-rooms').onclick=()=>analysisSheet('rooms');
 drawAnalysisChart(true);drawComparison();applyEvidence();animateMetric(mean,true);
 const scrub=document.getElementById('chart-scrubber');scrub.oninput=()=>selectAnalysisPoint(Number(scrub.value));
 const plot=document.getElementById('occupancy-plot');let held=false;
 const pick=e=>{const r=plot.getBoundingClientRect();selectAnalysisPoint(Math.round(Math.max(0,Math.min(1,(e.clientX-r.left-r.width*32/360)/(r.width*308/360)))*(analysisData().length-1)))};
 plot.onpointerdown=e=>{if(e.target===scrub)return;held=true;plot.setPointerCapture(e.pointerId);pick(e)};
 plot.onpointermove=e=>{if(held||e.pointerType==='mouse')pick(e)};plot.onpointerup=plot.onpointercancel=()=>{held=false};
}
let metricFrame=0,morphFrame=0,currentPlotValues=null;
function animateMetric(value,initial=false){cancelAnimationFrame(metricFrame);const el=document.getElementById('occupancy-value');if(!el)return;const from=initial?Math.max(0,value-12):Number(el.textContent),start=performance.now();function frame(now){if(!el.isConnected)return;const t=motion()?Math.min(1,(now-start)/(initial?650:180)):1;el.textContent=pct(from+(value-from)*(1-Math.pow(1-t,4)));if(t<1)metricFrame=requestAnimationFrame(frame)}metricFrame=requestAnimationFrame(frame);}
const aSvg=(tag,attrs)=>{const el=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el};
function aText(svg,x,y,text,attrs={}){const el=aSvg('text',{x,y,fill:ANALYSIS_COLORS.MUT,'font-size':11,...attrs});el.textContent=text;svg.append(el);return el;}
const aX=(i,n)=>32+i*308/(n-1),aY=v=>205-v*1.6;
function drawAnalysisChart(enter=false,previous=null){
 cancelAnimationFrame(morphFrame);const svg=document.getElementById('occupancy-chart'),data=analysisData();svg.innerHTML='';
 [0,50,100].forEach(v=>{svg.append(aSvg('line',{x1:32,y1:aY(v),x2:340,y2:aY(v),stroke:ANALYSIS_COLORS.GRID,'stroke-width':.7,'stroke-dasharray':v?'2 5':'none'}));aText(svg,25,aY(v)+4,String(v),{'text-anchor':'end','font-size':10})});
 data.forEach((d,i)=>svg.append(aSvg('line',{x1:aX(i,data.length),y1:205,x2:aX(i,data.length),y2:198,stroke:ANALYSIS_COLORS.GRID,'stroke-width':.8})));
 const path=aSvg('path',{id:'analysis-line',fill:'none',stroke:ANALYSIS_COLORS.DATA,'stroke-width':2,pathLength:1,class:enter?'analysis-draw':''});svg.append(path);
 const dots=data.map((d,i)=>{const dot=aSvg('circle',{class:'analysis-point',cx:aX(i,data.length),cy:aY(d.v),r:analysisState.range===7?3.5:2.3,fill:d.weekend?ANALYSIS_COLORS.BG:ANALYSIS_COLORS.DATA,stroke:ANALYSIS_COLORS.DATA,'stroke-width':1.4,'data-index':i});svg.append(dot);return dot});
 [0,Math.floor((data.length-1)/2),data.length-1].forEach(i=>aText(svg,aX(i,data.length),230,dateLabel(data[i].date),{'text-anchor':i===0?'start':i===data.length-1?'end':'middle','font-size':11}));
 svg.append(aSvg('line',{id:'selected-guide',x1:0,x2:0,y1:38,y2:205,stroke:ANALYSIS_COLORS.HERO,'stroke-dasharray':'3 4',visibility:'hidden'}));
 const dest=data.map(d=>d.v),start=performance.now();const interp=(a,t)=>{const q=t*(a.length-1),i=Math.floor(q);return a[i]+((a[Math.min(i+1,a.length-1)]-a[i])*(q-i))};
 function paint(now){if(!svg.isConnected)return;const t=previous&&motion()?Math.min(1,(now-start)/440):1;const eased=1-Math.pow(1-t,4);currentPlotValues=dest.map((v,i)=>previous?interp(previous,i/(dest.length-1))*(1-eased)+v*eased:v);path.setAttribute('d','M'+currentPlotValues.map((v,i)=>`${aX(i,dest.length)} ${aY(v)}`).join(' L '));dots.forEach((dot,i)=>dot.setAttribute('cy',aY(currentPlotValues[i])));if(t<1)morphFrame=requestAnimationFrame(paint)}paint(start);
}
function selectAnalysisPoint(index){const data=analysisData();analysisState.index=index;const tooltip=document.getElementById('chart-tooltip'),guide=document.getElementById('selected-guide');if(index===null){tooltip.hidden=true;guide.setAttribute('visibility','hidden');animateMetric(average(data));document.getElementById('analysis-period').textContent=dateLabel(data[0].date)+' – '+dateLabel(data.at(-1).date);document.getElementById('analysis-delta').textContent=analysisState.range===7?tr('↑ 5 percentage points from last week','↑ 较上周提升 5 个百分点'):tr('Four-week average · Sample bookings','四周平均 · 示例预订');}else{const d=data[index],x=aX(index,data.length);tooltip.hidden=false;tooltip.innerHTML=`<b>${dateLabel(d.date)}</b><span>${tr('Occupancy','入住率')} ${d.v}%</span>`;tooltip.style.left=Math.max(20,Math.min(80,x/360*100))+'%';guide.setAttribute('x1',x);guide.setAttribute('x2',x);guide.setAttribute('visibility','visible');animateMetric(d.v);document.getElementById('analysis-period').textContent=dateLabel(d.date);document.getElementById('analysis-delta').textContent=tr('Daily reading · Sample data','单日读数 · 示例数据');const input=document.getElementById('chart-scrubber');input.value=index;input.setAttribute('aria-valuetext',`${dateLabel(d.date)}, ${d.v}%`)}document.querySelectorAll('.analysis-point').forEach((dot,i)=>{dot.classList.toggle('chosen',i===index);dot.setAttribute('r',i===index?5:analysisState.range===7?3.5:2.3)})}
function drawComparison(){const svg=document.getElementById('day-comparison-chart'),data=analysisData();svg.innerHTML='';[[tr('Weekdays','工作日'),average(data.filter(d=>!d.weekend))],[tr('Weekends','周末'),average(data.filter(d=>d.weekend))]].forEach(([name,v],i)=>{const y=31+i*67;aText(svg,0,y,name,{'font-size':14,fill:ANALYSIS_COLORS.TXT});aText(svg,355,y,pct(v)+'%',{'text-anchor':'end','font-size':22,fill:ANALYSIS_COLORS.TXT});svg.append(aSvg('line',{x1:0,y1:y+27,x2:350,y2:y+27,stroke:ANALYSIS_COLORS.GRID,'stroke-width':1}));for(let k=0;k<Math.floor(v);k++){const x=k*3.5+1.75;svg.append(aSvg('line',{x1:x,y1:y+25,x2:x,y2:y+10,stroke:ANALYSIS_COLORS.DATA,'stroke-width':1.8,class:'comparison-tick',style:`animation-delay:${i*.1+k*.008}s`}));if(k%5===4)svg.append(aSvg('circle',{cx:x,cy:y+31,r:.7,fill:ANALYSIS_COLORS.MUT}))}if(v%1)svg.append(aSvg('line',{x1:Math.floor(v)*3.5+1.75,y1:y+25,x2:Math.floor(v)*3.5+1.75,y2:y+10,stroke:ANALYSIS_COLORS.DATA,'stroke-width':1.8*(v%1)}));});}
function applyEvidence(){const open=analysisState.why,button=document.getElementById('analysis-why'),panel=document.getElementById('analysis-evidence');button.setAttribute('aria-expanded',String(open));button.querySelector('span').textContent=open?'−':'+';panel.classList.toggle('expanded',open);panel.inert=!open;const data=analysisData(),total=data.reduce((s,d)=>s+100-d.v,0),early=data.filter(d=>d.date.getDay()>=1&&d.date.getDay()<=4);document.getElementById('availability-share').textContent=Math.round(early.reduce((s,d)=>s+100-d.v,0)/total*100)+'%';document.querySelectorAll('.analysis-point').forEach((p,i)=>{const match=data[i].date.getDay()>=1&&data[i].date.getDay()<=4;p.classList.toggle('evidence-point',open&&match);p.style.opacity=open&&!match?'.35':'1'});document.getElementById('occupancy-plot').classList.toggle('show-evidence',open);}
function switchAnalysisRange(range){if(range===analysisState.range){selectAnalysisPoint(null);return;}const previous=currentPlotValues?.slice();analysisState.range=range;analysisState.index=null;document.querySelectorAll('[data-range]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.range)===range)));const data=analysisData(),input=document.getElementById('chart-scrubber');input.max=data.length-1;input.value=0;document.querySelector('.chart-data tbody').innerHTML=data.map(d=>`<tr><td>${dateLabel(d.date)}</td><td>${d.v}%</td></tr>`).join('');drawAnalysisChart(false,previous);drawComparison();applyEvidence();selectAnalysisPoint(null);const w=pct(average(data.filter(d=>!d.weekend))),e=pct(average(data.filter(d=>d.weekend)));document.getElementById('day-comparison-chart').setAttribute('aria-label',tr(`Weekdays ${w}%, weekends ${e}%`,`工作日 ${w}%，周末 ${e}%`));}
function analysisSheet(type){sheet.innerHTML=`<div class="sheet-close-row"><span class="sample-label">${tr('ANALYSIS · DEMO','经营分析 · 示例')}</span><button class="round" id="analysis-sheet-close" aria-label="${tr('Close','关闭')}">×</button></div><h2 id="activity-title"></h2><div id="analysis-sheet-body"></div>`;sheet.querySelector('#analysis-sheet-close').onclick=()=>sheet.close();const title=sheet.querySelector('h2'),body=sheet.querySelector('#analysis-sheet-body');if(type==='rooms'){title.textContent=tr('Every room has a story.','看看各房型的表现。');body.innerHTML=`<p class="analysis-source">${tr('Sep 14–20 · Booked / available room nights','9 月 14–20 日 · 已订 / 可售间夜')}</p><table class="room-table"><thead><tr><th>${tr('Room type','房型')}</th><th>${tr('Nights','间夜')}</th><th>${tr('Occupancy','入住率')}</th></tr></thead><tbody>${[['Garden','花园房',18,21],['Courtyard','庭院房',15,21],['Standard','标准房',16,28]].map(([en,zh,n,a])=>`<tr><td>${tr(en,zh)}</td><td>${n} / ${a}</td><td>${Math.round(n/a*100)}%</td></tr>`).join('')}</tbody></table><p class="analysis-source">${tr('Total: 49 / 70 room nights = 70%. Displayed rates are rounded.','总计：49 / 70 间夜 = 70%。房型比例已取整。')}</p>`;}else{title.textContent=tr('Try a weekday stay offer.','试试工作日住宿推广。');body.innerHTML=`<p>${tr('Speak to guests who can travel Monday–Thursday. Lead with a quieter stay and flexible dates, rather than an unverified discount.','面向周一至周四可出行的客人，突出安静住宿与灵活日期，不预设未经确认的折扣。')}</p><p class="analysis-source">${tr('Based on demo bookings · Check your costs and availability first.','依据示例预订 · 请先核对成本及可订日期。')}</p><button class="confirm-task" id="analysis-create">${tr('Create promotion','创建推广文案')} ${svg('arrow')}</button><p class="confirm-note">${tr('You review every draft. Nothing is published automatically.','每份草稿都由你审核，不会自动发布。')}</p>`;body.querySelector('#analysis-create').onclick=()=>{title.textContent=tr('A weekday story, ready to shape.','起草你的工作日住宿故事。');body.innerHTML=`<label class="draft-label" for="analysis-promotion">${tr('Promotion draft · Sample','推广草稿 · 示例')}</label><textarea id="analysis-promotion" rows="6"></textarea><button class="confirm-task" id="analysis-save-draft">${tr('Save to Work for review','保存到工作区审核')} ${svg('arrow')}</button><p class="confirm-note">${tr('Create preview · Not published','创作预览 · 未发布')}</p>`;body.querySelector('textarea').value=tx(tasks.promotion.draft);body.querySelector('#analysis-save-draft').onclick=()=>{const field=body.querySelector('textarea');if(!field.value.trim()){field.setCustomValidity(tr('Please add draft content.','请输入草稿内容。'));field.reportValidity();field.oninput=()=>field.setCustomValidity('');return;}savedDrafts.promotion=field.value;workState.confirmed=workState.confirmed.filter(id=>id!=='promotion');sheet.close();location.hash='work/promotion';announce(tr('Draft saved to Work for your review.','草稿已保存至工作区，等待审核。'))};};}sheet.showModal();}

render();
